import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer} from 'react-relay'

import type {AgentPageEntryPoint} from '../../pages/AgentsPages/AgentPage/AgentPage.entryPoint'
import type {AgentPipelinePageEntryPoint} from '../../pages/PipelinesPages/AgentsPage/Agent/AgentPipelinePage.entryPoint'

export type AppAgentTypeNestedEntryPoints = {
  pipeline?: typeof AgentPipelinePageEntryPoint
  common?: typeof AgentPageEntryPoint
}

export default function AppAgent({
  entryPoints,
}: EntryPointProps<{}, AppAgentTypeNestedEntryPoints, {}, {}>) {
  const {pipeline, common} = entryPoints

  if (pipeline) {
    return <EntryPointContainer entryPointReference={pipeline} props={{}} />
  }

  if (common) {
    return <EntryPointContainer entryPointReference={common} props={{}} />
  }

  return null
}
export type AppAgentTypeComponent = typeof AppAgent
